input.sparql:
SELECT ?ts ?p WHERE {
  ?z a brick:Zone ; rdfs:label ?lbl .
  FILTER(?lbl IN ("Perimeter_top_ZN_3","Perimeter_mid_ZN_3"))
  ?s brick:hasSubCategory ?z .
  ?s a brick:AirTemperatureSensor ; ref:hasTimeseriesId ?ts .
}

SELECT ?zlbl ?ts WHERE {
  ?z a brick:Zone ; rdfs:label ?zlbl .
  ?p brick:hasSubCategory ?z .
  ?p a brick:AirTemperatureSensor ; ref:hasTimeseriesId ?ts .
}

SELECT ?p ?lbl ?ts ?rel WHERE {
  ?p a brick:AirTemperatureSensor ; rdfs:label ?lbl ; ref:hasTimeseriesId ?ts .
} LIMIT 10

